    private readonly TextBox _construct=new();private readonly TextBox _citation=new();private readonly TextBox _validation=new(){AcceptsReturn=true,MinHeight=48};
    private readonly CheckBox _active=new();private readonly ComboBox _placement=new(){ItemsSource=new[]{QuestionnairePlacements.PreExperiment,QuestionnairePlacements.PostExperiment},SelectedIndex=1};
    private readonly TextBox _sectionTitle=new();private readonly TextBox _questionText=new(){AcceptsReturn=true,MinHeight=52};private readonly TextBox _variableName=new();
    private readonly ComboBox _questionType=new(){ItemsSource=QuestionnaireQuestionTypes.Supported,SelectedIndex=0};private readonly CheckBox _required=new();private readonly TextBox _options=new(){AcceptsReturn=true,MinHeight=80,PlaceholderText="Label | numeric code"};
    private readonly StackPanel _questions=new(){Spacing=6};private readonly TextBox _scaleName=new();private readonly TextBox _scaleVariable=new();private readonly TextBox _scaleItems=new(){PlaceholderText="item_one, -reverse_item"};private readonly ComboBox _scaleMethod=new(){ItemsSource=new[]{"MEAN","SUM"},SelectedIndex=0};private readonly NumericUpDown _scaleMinimum=new(){Minimum=1,Maximum=100,Value=1};private readonly StackPanel _scales=new(){Spacing=5};private readonly TextBlock _status=new(){TextWrapping=TextWrapping.Wrap};
    private List<Questionnaire> _questionnaires=[];private Questionnaire? _selected;private QuestionnaireVersion? _version;

    public QuestionnaireWorkspaceView(Study study)
    {
        _study=study;var arabic=LocalizationService.IsArabic;FlowDirection=arabic?FlowDirection.RightToLeft:FlowDirection.LeftToRight;
        var root=new Grid{ColumnDefinitions=new ColumnDefinitions("240,16,*"),RowDefinitions=new RowDefinitions("Auto,12,*"),Margin=new Thickness(0)};
        var heading=new StackPanel{Spacing=4};heading.Children.Add(new TextBlock{Text=T("الاستبيانات والمقاييس","Questionnaires and measures"),Classes={"pageTitle"}});heading.Children.Add(new TextBlock{Text=T("أنشئ أدوات مخصصة قابلة للإصدار مع حفظ الإجابات الخام وقواعد التصحيح","Create versioned custom instruments while preserving raw answers and scoring rules"),Foreground=Brush("#66758A"),TextWrapping=TextWrapping.Wrap});Grid.SetColumnSpan(heading,3);root.Children.Add(heading);
        var left=new StackPanel{Spacing=8};var newButton=Button(T("استبيان جديد","New questionnaire"),true);newButton.Click+=async(_,_)=>await CreateAsync();left.Children.Add(newButton);left.Children.Add(_list);_list.SelectionChanged+=async(_,_)=>await SelectAsync(_list.SelectedIndex);Grid.SetRow(left,2);root.Children.Add(left);
        var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};var editor=new StackPanel{Spacing=12};scroll.Content=editor;Grid.SetColumn(scroll,2);Grid.SetRow(scroll,2);root.Children.Add(scroll);
        editor.Children.Add(Field(T("العنوان","Title"),_title));editor.Children.Add(Field(T("الغرض والوصف","Purpose and description"),_description));
        var metadata=new Grid{ColumnDefinitions=new ColumnDefinitions("*,12,*")};metadata.Children.Add(Field(T("البناء المقاس","Construct"),_construct));var citationField=Field(T("المرجع الاختياري","Optional citation"),_citation);Grid.SetColumn(citationField,2);metadata.Children.Add(citationField);editor.Children.Add(metadata);editor.Children.Add(Field(T("ملاحظات الصدق أو الثبات","Validation or reliability notes"),_validation));
        _active.Content=T("نشط","Active");editor.Children.Add(_active);var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};var save=Button(T("حفظ البيانات الوصفية","Save metadata"),true);save.Click+=async(_,_)=>await SaveAsync();var duplicate=Button(T("تكرار","Duplicate"));duplicate.Click+=async(_,_)=>await DuplicateAsync();var version=Button(T("إصدار جديد","New version"));version.Click+=async(_,_)=>await NewVersionAsync();var publish=Button(T("نشر الإصدار وقفله","Publish and lock version"));publish.Click+=async(_,_)=>await PublishAsync();var preview=Button(T("معاينة","Preview"));preview.Click+=(_,_)=>Preview();actions.Children.Add(save);actions.Children.Add(duplicate);actions.Children.Add(version);actions.Children.Add(publish);actions.Children.Add(preview);editor.Children.Add(actions);
        var assignmentRow=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};assignmentRow.Children.Add(_placement);var assign=Button(T("تعيين للمرحلة","Assign placement"));assign.Click+=async(_,_)=>await AssignAsync();assignmentRow.Children.Add(assign);editor.Children.Add(Field(T("مرحلة العرض","Participant placement"),assignmentRow));
