        var qGrid=new Grid{ColumnDefinitions=new ColumnDefinitions("*,12,*")};qGrid.Children.Add(Field(T("اسم المتغير","Variable name"),_variableName));var typeField=Field(T("نوع السؤال","Question type"),_questionType);Grid.SetColumn(typeField,2);qGrid.Children.Add(typeField);editor.Children.Add(qGrid);editor.Children.Add(Field(T("نص السؤال","Question text"),_questionText));_required.Content=T("مطلوب","Required");editor.Children.Add(_required);editor.Children.Add(Field(T("الخيارات مرتبة، خيار واحد في كل سطر","Ordered options, one per line"),_options));var addQuestion=Button(T("إضافة سؤال","Add question"),true);addQuestion.Click+=async(_,_)=>await AddQuestionAsync();editor.Children.Add(addQuestion);editor.Children.Add(_questions);
        editor.Children.Add(new TextBlock{Text=T("المقاييس المشتقة","Derived scales"),Classes={"sectionTitle"}});var scaleIdentity=new Grid{ColumnDefinitions=new ColumnDefinitions("*,12,*")};scaleIdentity.Children.Add(Field(T("اسم المقياس","Scale name"),_scaleName));var scaleVariableField=Field(T("اسم متغير الدرجة","Score variable name"),_scaleVariable);Grid.SetColumn(scaleVariableField,2);scaleIdentity.Children.Add(scaleVariableField);editor.Children.Add(scaleIdentity);editor.Children.Add(Field(T("متغيرات البنود مفصولة بفاصلة، واستخدم - قبل البند المعكوس","Comma-separated item variables; prefix reverse-coded items with -"),_scaleItems));var scaleRules=new Grid{ColumnDefinitions=new ColumnDefinitions("*,12,*")};scaleRules.Children.Add(Field(T("قاعدة التصحيح","Scoring rule"),_scaleMethod));var minimumField=Field(T("الحد الأدنى للبنود المجاب عنها","Minimum answered items"),_scaleMinimum);Grid.SetColumn(minimumField,2);scaleRules.Children.Add(minimumField);editor.Children.Add(scaleRules);var addScale=Button(T("إضافة مقياس","Add scale"));addScale.Click+=async(_,_)=>await AddScaleAsync();editor.Children.Add(addScale);editor.Children.Add(_scales);editor.Children.Add(_status);
