    public async Task ReloadAsync(){_questionnaires=await QuestionnaireRepository.GetByStudyAsync(_study.Id);_list.ItemsSource=_questionnaires.Select(item=>item.Versions.Count==0?$"{item.Title}  ·  legacy":$"{item.Title}  ·  v{item.Versions.Max(version=>version.VersionNumber)}").ToArray();if(_questionnaires.Count>0){_list.SelectedIndex=Math.Clamp(_list.SelectedIndex,0,_questionnaires.Count-1);await SelectAsync(_list.SelectedIndex);}else Clear();}
    private async Task CreateAsync(){var questionnaire=new Questionnaire{StudyId=_study.Id,Title=T("استبيان مخصص جديد","New custom questionnaire"),Description=T("أداة مخصصة أنشأها الباحث وليست أداة معتمدة","Custom Researcher Instrument; no validation is implied"),InstrumentType=QuestionnaireLicenseStatuses.Custom};var version=new QuestionnaireVersion{QuestionnaireId=questionnaire.Id,VersionLabel="Version 1",Language=LocalizationService.IsArabic?"ar":"en",InstrumentType=QuestionnaireLicenseStatuses.Custom,LicenseStatus=QuestionnaireLicenseStatuses.Custom,RedistributionStatus=QuestionnaireLicenseStatuses.UserProvided,ValidationNotes=T("أداة مخصصة أنشأها الباحث","Custom Researcher Instrument")};version.Sections.Add(new QuestionnaireSection{QuestionnaireVersionId=version.Id,Title=T("القسم الرئيسي","Main section")});await QuestionnaireRepository.CreateAsync(questionnaire,version);await ReloadAsync();_list.SelectedIndex=_questionnaires.Count-1;}
    private Task SelectAsync(int index){if(index<0||index>=_questionnaires.Count){Clear();return Task.CompletedTask;}_selected=_questionnaires[index];_version=_selected.Versions.OrderByDescending(item=>item.VersionNumber).FirstOrDefault();_title.Text=_selected.Title;_description.Text=_selected.Description;_active.IsChecked=_selected.IsActive;if(_version is null){_construct.Text=_citation.Text=_validation.Text="";RenderQuestions();_status.Text=T("استبيان قديم محفوظ للقراءة فقط ولم يتم تحويله تلقائيا","Legacy questionnaire preserved for read-only compatibility");return Task.CompletedTask;}_construct.Text=_version.Construct;_citation.Text=_version.Citation;_validation.Text=_version.ValidationNotes;RenderQuestions();_status.Text=_version.IsImmutable?T("هذا الإصدار مقفل لحماية الاستجابات التاريخية","This version is immutable to protect historical responses"):T("مسودة قابلة للتحرير","Editable draft");return Task.CompletedTask;}
    private async Task SaveAsync(){if(_selected is null||_version is null)return;_selected.Title=_title.Text?.Trim()??"";_selected.Description=_description.Text;_selected.IsActive=_active.IsChecked==true;_version.Construct=_construct.Text;_version.Citation=_citation.Text;_version.ValidationNotes=_validation.Text;await QuestionnaireRepository.UpdateQuestionnaireAsync(_selected);if(!_version.IsImmutable)await QuestionnaireRepository.UpdateVersionMetadataAsync(_version);await ReloadAsync();}
    private async Task DuplicateAsync(){if(_selected is null)return;await QuestionnaireRepository.DuplicateAsync(_selected.Id,$"{_selected.Title} — Copy");await ReloadAsync();}
    private async Task NewVersionAsync(){if(_selected is null)return;await QuestionnaireRepository.CreateNewVersionAsync(_selected.Id);await ReloadAsync();}
    private async Task PublishAsync(){if(_selected is null||_version is null)return;try{await QuestionnaireRepository.PublishVersionAsync(_selected.Id,_version.Id);await ReloadAsync();}catch(Exception ex){Show(ex.Message);}}
    private async Task AssignAsync(){if(_selected is null||_version is null)return;try{await QuestionnaireRepository.AssignAsync(new QuestionnaireAssignment{StudyId=_study.Id,QuestionnaireVersionId=_version.Id,Placement=Convert.ToString(_placement.SelectedItem)??QuestionnairePlacements.PostExperiment});Show(T("تم حفظ التعيين","Placement saved"));}catch(Exception ex){Show(ex.Message);}}
    private async Task AddSectionAsync(){if(_version is null||string.IsNullOrWhiteSpace(_sectionTitle.Text))return;try{await QuestionnaireRepository.AddSectionAsync(new QuestionnaireSection{QuestionnaireVersionId=_version.Id,Title=_sectionTitle.Text.Trim(),SortOrder=_version.Sections.Count});_sectionTitle.Text="";await ReloadAsync();}catch(Exception ex){Show(ex.Message);}}
    private async Task AddQuestionAsync(){if(_version is null||string.IsNullOrWhiteSpace(_questionText.Text)||string.IsNullOrWhiteSpace(_variableName.Text))return;try{var type=Convert.ToString(_questionType.SelectedItem)??QuestionnaireQuestionTypes.Likert;var question=new Question{QuestionnaireVersionId=_version.Id,SectionId=_version.Sections.FirstOrDefault()?.Id,VariableName=_variableName.Text.Trim(),QuestionText=_questionText.Text.Trim(),QuestionType=type,MeasurementLevel=type is QuestionnaireQuestionTypes.Likert or QuestionnaireQuestionTypes.SingleChoice?MeasurementLevels.Ordinal:type==QuestionnaireQuestionTypes.Numeric?MeasurementLevels.Continuous:type==QuestionnaireQuestionTypes.YesNo?MeasurementLevels.Binary:MeasurementLevels.Nominal,IsRequired=_required.IsChecked==true,SortOrder=_version.Questions.Count};question.Options=ParseOptions(question,type);await QuestionnaireRepository.AddQuestionAsync(question);_questionText.Text=_variableName.Text=_options.Text="";await ReloadAsync();}catch(Exception ex){Show(ex.Message);}}
    private async Task AddScaleAsync(){if(_version is null||string.IsNullOrWhiteSpace(_scaleName.Text)||string.IsNullOrWhiteSpace(_scaleVariable.Text)||string.IsNullOrWhiteSpace(_scaleItems.Text))return;try{var tokens=_scaleItems.Text.Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);var items=new List<QuestionnaireScaleItem>();foreach(var token in tokens){var reverse=token.StartsWith("-",StringComparison.Ordinal);var variable=reverse?token[1..].Trim():token;var question=_version.Questions.SingleOrDefault(item=>string.Equals(item.VariableName,variable,StringComparison.OrdinalIgnoreCase))??throw new InvalidOperationException($"Question variable '{variable}' was not found.");double? minimum=null,maximum=null;if(reverse){var bounds=question.Options.Where(item=>item.NumericCode.HasValue).Select(item=>item.NumericCode!.Value).ToArray();if(bounds.Length<2)throw new InvalidOperationException($"Reverse-coded item '{variable}' requires bounded numeric options.");minimum=bounds.Min();maximum=bounds.Max();}items.Add(new QuestionnaireScaleItem{QuestionId=question.Id,IsReverseCoded=reverse,ReverseMinimum=minimum,ReverseMaximum=maximum});}var scale=new QuestionnaireScale{QuestionnaireVersionId=_version.Id,Name=_scaleName.Text.Trim(),VariableName=_scaleVariable.Text.Trim(),ScoringMethod=Convert.ToString(_scaleMethod.SelectedItem)??"MEAN",MinimumAnsweredItems=Math.Clamp(Convert.ToInt32(_scaleMinimum.Value??1),1,items.Count),Items=items};await QuestionnaireRepository.AddScaleAsync(scale);_scaleName.Text=_scaleVariable.Text=_scaleItems.Text="";await ReloadAsync();}catch(Exception exception){Show(exception.Message);}}
    private List<QuestionOption> ParseOptions(Question question,string type){var lines=(_options.Text??"").Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(lines.Length==0&&type==QuestionnaireQuestionTypes.Likert)lines=["Strongly disagree|1","Disagree|2","Neither agree nor disagree|3","Agree|4","Strongly agree|5"];return lines.Select((line,index)=>{var parts=line.Split('|',2,StringSplitOptions.TrimEntries);double? numeric=parts.Length>1&&double.TryParse(parts[1],out var value)?value:null;return new QuestionOption{QuestionId=question.Id,ValueCode=(numeric??index+1).ToString()!,NumericCode=numeric,DisplayLabel=parts[0],SortOrder=index};}).ToList();}
    private void Preview(){if(_selected is null||_version is null)return;var assignment=new QuestionnaireAssignment{QuestionnaireVersionId=_version.Id,Questionnaire=_selected,Version=_version,Placement=Convert.ToString(_placement.SelectedItem)??QuestionnairePlacements.PostExperiment};var window=new Window{Title=T("معاينة الاستبيان","Questionnaire preview"),Width=760,Height=720,Content=new ParticipantQuestionnaireView(assignment,null,true)};if(TopLevel.GetTopLevel(this) is Window owner)window.Show(owner);else window.Show();}
    private void RenderQuestions(){_questions.Children.Clear();_scales.Children.Clear();if(_version is null)return;var ordered=_version.Questions.OrderBy(item=>item.SortOrder).ToArray();for(var index=0;index<ordered.Length;index++){var question=ordered[index];var row=new Grid{ColumnDefinitions=new ColumnDefinitions("*,Auto,Auto")};row.Children.Add(new TextBlock{Text=$"{index+1}. {question.QuestionText}  ·  {question.QuestionType}{(question.IsRequired?"  ·  required":"")}",TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center});var up=MoveButton("M4,10 L8,6 L12,10 M8,6 L8,14",T("نقل إلى أعلى","Move up"));up.IsEnabled=index>0&&!_version.IsImmutable;var down=MoveButton("M4,10 L8,14 L12,10 M8,4 L8,14",T("نقل إلى أسفل","Move down"));down.IsEnabled=index<ordered.Length-1&&!_version.IsImmutable;var current=index;up.Click+=async(_,_)=>await MoveQuestionAsync(ordered,current,-1);down.Click+=async(_,_)=>await MoveQuestionAsync(ordered,current,1);Grid.SetColumn(up,1);Grid.SetColumn(down,2);row.Children.Add(up);row.Children.Add(down);_questions.Children.Add(new Border{Padding=new Thickness(10,8),Background=Brush("#F5F7FA"),CornerRadius=new CornerRadius(7),Child=row});}foreach(var scale in _version.Scales)_scales.Children.Add(new TextBlock{Text=$"{scale.Name}  ·  {scale.ScoringMethod}  ·  {scale.Items.Count} items  ·  min {scale.MinimumAnsweredItems}",TextWrapping=TextWrapping.Wrap});}
    private async Task MoveQuestionAsync(Question[] ordered,int index,int direction){var target=index+direction;if(target<0||target>=ordered.Length)return;try{var currentOrder=ordered[index].SortOrder;var targetOrder=ordered[target].SortOrder;await QuestionnaireRepository.MoveQuestionAsync(ordered[index].Id,targetOrder);await QuestionnaireRepository.MoveQuestionAsync(ordered[target].Id,currentOrder);await ReloadAsync();}catch(Exception exception){Show(exception.Message);}}
    private async Task DuplicateQuestionAsync(Question question){if(_version?.IsImmutable!=false)return;try{await QuestionnaireRepository.DuplicateQuestionAsync(question);await ReloadAsync();}catch(Exception exception){Show(exception.Message);}}
    private async Task DeleteQuestionAsync(Question question){if(_version?.IsImmutable!=false)return;try{await QuestionnaireRepository.DeleteQuestionAsync(question.Id);await ReloadAsync();}catch(Exception exception){Show(exception.Message);}}
    private async Task EditQuestionAsync(Question question){if(_version?.IsImmutable!=false)return;var text=new TextBox{Text=question.QuestionText,AcceptsReturn=true,MinHeight=70};var required=new CheckBox{Content="Required",IsChecked=question.IsRequired};var save=Button("Save",true);var panel=new StackPanel{Spacing=10,Margin=new Thickness(18),Children={Field("Question text",text),required,save}};var window=new Window{Title="Edit question",Width=520,Height=260,Content=panel};save.Click+=async(_,_)=>{if(string.IsNullOrWhiteSpace(text.Text))return;question.QuestionText=text.Text.Trim();question.IsRequired=required.IsChecked==true;await QuestionnaireRepository.UpdateQuestionAsync(question);window.Close();await ReloadAsync();};if(TopLevel.GetTopLevel(this) is Window owner)await window.ShowDialog(owner);else window.Show();}
    private void Clear(){_selected=null;_version=null;_title.Text=_description.Text=_construct.Text=_citation.Text=_validation.Text="";_questions.Children.Clear();}
    private void Show(string value)=>_status.Text=value;
    private static StackPanel Field(string label,Control control)=>new(){Spacing=5,Children={new TextBlock{Text=label,Classes={"metadata"}},control}};
    private static Button Button(string label,bool primary=false){var button=new Button{Content=label,HorizontalContentAlignment=HorizontalAlignment.Center};button.Classes.Add(primary?"primary":"secondary");return button;}
    private static Button MoveButton(string data,string accessibleName){var button=new Button{Content=new Path{Data=StreamGeometry.Parse(data),Stroke=Brush("#52647C"),StrokeThickness=1.7,StrokeLineCap=PenLineCap.Round,StrokeJoin=PenLineJoin.Round,Width=16,Height=16,Stretch=Stretch.Uniform},Width=34,Height=34,HorizontalContentAlignment=HorizontalAlignment.Center};button.Classes.Add("iconAction");ToolTip.SetTip(button,accessibleName);AutomationProperties.SetName(button,accessibleName);return button;}
    private static string T(string ar,string en)=>UiTextService.Localized(ar,en);private static SolidColorBrush Brush(string value)=>new(Color.Parse(value));

    protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e){base.OnAttachedToVisualTree(e);LayoutUpdated+=(_,_)=>DecorateQuestionRows();DispatcherTimer.RunOnce(DecorateQuestionRows,TimeSpan.FromMilliseconds(350));}
    private async Task EditQuestionAdvancedAsync(Question question){if(_version?.IsImmutable!=false)return;var variable=new TextBox{Text=question.VariableName};var text=new TextBox{Text=question.QuestionText,AcceptsReturn=true,MinHeight=68};var type=new ComboBox{ItemsSource=QuestionnaireQuestionTypes.Supported,SelectedItem=question.QuestionType};var required=new CheckBox{Content=T("مطلوب","Required"),IsChecked=question.IsRequired};var options=new TextBox{AcceptsReturn=true,MinHeight=75,Text=string.Join(Environment.NewLine,question.Options.OrderBy(x=>x.SortOrder).Select(x=>$"{x.DisplayLabel} | {x.NumericCode?.ToString() ?? x.ValueCode}"))};var minimum=new NumericUpDown{Minimum=-1000,Maximum=1000,Value=1};var maximum=new NumericUpDown{Minimum=-1000,Maximum=1000,Value=5};var minLabel=new TextBox();var maxLabel=new TextBox();var config=new StackPanel{Spacing=8};void Configure(){config.Children.Clear();var selected=Convert.ToString(type.SelectedItem)??QuestionnaireQuestionTypes.ShortText;if(selected is QuestionnaireQuestionTypes.Likert or QuestionnaireQuestionTypes.SingleChoice or QuestionnaireQuestionTypes.MultipleChoice)config.Children.Add(Field(T("خيارات الإجابة، خيار في كل سطر","Answer options, one per line"),options));if(selected is QuestionnaireQuestionTypes.Likert or QuestionnaireQuestionTypes.Numeric){var bounds=new Grid{ColumnDefinitions=new ColumnDefinitions("*,10,*")};bounds.Children.Add(Field(T("الحد الأدنى","Minimum"),minimum));var high=Field(T("الحد الأقصى","Maximum"),maximum);Grid.SetColumn(high,2);bounds.Children.Add(high);config.Children.Add(bounds);}if(selected==QuestionnaireQuestionTypes.Likert){config.Children.Add(Field(T("تسمية الحد الأدنى","Minimum label"),minLabel));config.Children.Add(Field(T("تسمية الحد الأقصى","Maximum label"),maxLabel));}}type.SelectionChanged+=(_,_)=>Configure();Configure();var save=Button(T("حفظ السؤال","Save question"),true);var panel=new StackPanel{Spacing=10,Margin=new Thickness(18),Children={Field(T("معرف السؤال","Question variable"),variable),Field(T("نص السؤال","Question text"),text),Field(T("نوع السؤال","Question type"),type),required,config,save}};var window=new Window{Title=T("تحرير السؤال","Edit question"),Width=620,Height=690,Content=new ScrollViewer{Content=panel}};save.Click+=async(_,_)=>{if(string.IsNullOrWhiteSpace(variable.Text)||string.IsNullOrWhiteSpace(text.Text))return;var selected=Convert.ToString(type.SelectedItem)??QuestionnaireQuestionTypes.ShortText;question.VariableName=variable.Text.Trim();question.QuestionText=text.Text.Trim();question.QuestionType=selected;question.IsRequired=required.IsChecked==true;question.MeasurementLevel=selected is QuestionnaireQuestionTypes.Likert or QuestionnaireQuestionTypes.SingleChoice?MeasurementLevels.Ordinal:selected==QuestionnaireQuestionTypes.Numeric?MeasurementLevels.Continuous:selected==QuestionnaireQuestionTypes.YesNo?MeasurementLevels.Binary:MeasurementLevels.Nominal;question.ConfigurationJson=JsonSerializer.Serialize(new{minimum=minimum.Value,maximum=maximum.Value,minimumLabel=minLabel.Text,maximumLabel=maxLabel.Text});var lines=(options.Text??string.Empty).Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);question.Options=lines.Select((line,index)=>{var parts=line.Split('|',2,StringSplitOptions.TrimEntries);var number=parts.Length>1&&double.TryParse(parts[1],out var parsed)?parsed:(double?)null;return new QuestionOption{QuestionId=question.Id,DisplayLabel=parts[0],ValueCode=(number??index+1).ToString(),NumericCode=number,SortOrder=index};}).ToList();await QuestionnaireRepository.UpdateQuestionAsync(question);window.Close();await ReloadAsync();};if(TopLevel.GetTopLevel(this) is Window owner)await window.ShowDialog(owner);else window.Show();}
    private void DecorateQuestionRows(){if(_version is null)return;var ordered=_version.Questions.OrderBy(item=>item.SortOrder).ToArray();for(var index=0;index<_questions.Children.Count&&index<ordered.Length;index++){if(_questions.Children[index] is not Border { Child: Grid row } || row.Tag is not null)continue;var question=ordered[index];row.Tag=question.Id;row.ColumnDefinitions=new ColumnDefinitions("*,Auto,Auto,Auto,Auto,Auto");var edit=Button(T("تحرير","Edit"));var duplicate=Button(T("تكرار","Duplicate"));var delete=Button(T("حذف","Delete"));var editable=!_version.IsImmutable;edit.IsEnabled=duplicate.IsEnabled=delete.IsEnabled=editable;edit.Click+=async(_,_)=>await EditQuestionAdvancedAsync(question);duplicate.Click+=async(_,_)=>await DuplicateQuestionAsync(question);delete.Click+=async(_,_)=>await DeleteQuestionAsync(question);Grid.SetColumn(edit,3);Grid.SetColumn(duplicate,4);Grid.SetColumn(delete,5);row.Children.Add(edit);row.Children.Add(duplicate);row.Children.Add(delete);}}
}
